package main

import "fmt"

func countAboveAverage(nums []int) int {
	total := 0
	for _, num := range nums {
		total += num
	}
	average := float64(total) / float64(len(nums))

	count := 0
	for _, num := range nums {
		if float64(num) > average {
			count++
		}
	}
	return count
}

func main() {
	var n int
	fmt.Scan(&n)
	nums := make([]int, n)
	for i := range nums {
		fmt.Scan(&nums[i])
	}
	fmt.Println(countAboveAverage(nums))
}
